package com.nm.fragmentsclean.editorialIntelligenceContext.write.adapters.secondary.gateways.repositories;
import com.nm.fragmentsclean.editorialIntelligenceContext.write.businesslogic.gateways.EditorialSignalAnalysisRepository; import com.nm.fragmentsclean.editorialIntelligenceContext.write.businesslogic.models.SourceSignal; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository; import java.util.*;
@Repository public final class JdbcEditorialSignalAnalysisRepository implements EditorialSignalAnalysisRepository {private final JdbcTemplate jdbc;public JdbcEditorialSignalAnalysisRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}public List<SourceSignal> newSignals(int limit){return jdbc.query("SELECT signal_id,source_id,external_id,title,summary,url,author,published_at,discovered_at,fingerprint FROM editorial_source_signals WHERE status='NEW' ORDER BY discovered_at,signal_id LIMIT ?",(rs,row)->new SourceSignal(rs.getObject("signal_id",UUID.class),rs.getObject("source_id",UUID.class),rs.getString("external_id"),rs.getString("title"),rs.getString("summary"),rs.getString("url"),rs.getString("author"),time(rs,"published_at"),time(rs,"discovered_at"),rs.getString("fingerprint")),Math.max(1,Math.min(100,limit)));}public void markAnalyzed(List<UUID> ids){for(var id:ids)jdbc.update("UPDATE editorial_source_signals SET status='ANALYZED' WHERE signal_id=? AND status='NEW'",id);}private static java.time.Instant time(java.sql.ResultSet rs,String col)throws java.sql.SQLException{var t=rs.getTimestamp(col);return t==null?null:t.toInstant();}}
